BEGIN TRANSACTION;
CREATE TABLE "exchanges_broker" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(500) NOT NULL UNIQUE);
CREATE TABLE "exchanges_exchange" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(20) NOT NULL UNIQUE, "name" varchar(100) NOT NULL, "website" varchar(200) NOT NULL);
CREATE TABLE "exchanges_news" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(500) NOT NULL, "published_at" date NOT NULL, "url" varchar(500) NOT NULL UNIQUE, "summary" text NOT NULL, "image_url" varchar(500) NOT NULL, "created_at" datetime NOT NULL, "exchange_id" bigint NOT NULL REFERENCES "exchanges_exchange" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "exchanges_parserun" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "started_at" datetime NOT NULL, "finished_at" datetime NULL, "status" varchar(10) NOT NULL, "trigger" varchar(20) NOT NULL, "date_from" date NULL, "date_to" date NULL, "rows_added" integer unsigned NOT NULL CHECK ("rows_added" >= 0), "rows_skipped" integer unsigned NOT NULL CHECK ("rows_skipped" >= 0), "error" text NOT NULL, "exchange_id" bigint NOT NULL REFERENCES "exchanges_exchange" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "exchanges_participant" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(500) NOT NULL, "bin" varchar(20) NOT NULL, CONSTRAINT "uniq_participant" UNIQUE ("name", "bin"));
CREATE TABLE "exchanges_product" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(500) NOT NULL, "code" varchar(50) NOT NULL, "tnved" varchar(30) NOT NULL, CONSTRAINT "uniq_product" UNIQUE ("name", "code", "tnved"));
CREATE TABLE "exchanges_trade" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "trade_date" date NOT NULL, "trade_time" time NULL, "deals_count" integer unsigned NULL CHECK ("deals_count" >= 0), "quantity" decimal NULL, "unit" varchar(30) NOT NULL, "price_open" decimal NULL, "price_close" decimal NULL, "price_min" decimal NULL, "price_max" decimal NULL, "price_avg" decimal NULL, "price_with_vat" decimal NULL, "price_without_vat" decimal NULL, "amount" decimal NULL, "delivery_basis" varchar(200) NOT NULL, "delivery_place" varchar(300) NOT NULL, "delivery_term" varchar(200) NOT NULL, "source_url" varchar(500) NOT NULL, "source_key" varchar(64) NOT NULL UNIQUE, "created_at" datetime NOT NULL, "buyer_id" bigint NULL REFERENCES "exchanges_participant" ("id") DEFERRABLE INITIALLY DEFERRED, "buyer_broker_id" bigint NULL REFERENCES "exchanges_broker" ("id") DEFERRABLE INITIALLY DEFERRED, "exchange_id" bigint NOT NULL REFERENCES "exchanges_exchange" ("id") DEFERRABLE INITIALLY DEFERRED, "parse_run_id" bigint NULL REFERENCES "exchanges_parserun" ("id") DEFERRABLE INITIALLY DEFERRED, "product_id" bigint NOT NULL REFERENCES "exchanges_product" ("id") DEFERRABLE INITIALLY DEFERRED, "seller_id" bigint NULL REFERENCES "exchanges_participant" ("id") DEFERRABLE INITIALLY DEFERRED, "seller_broker_id" bigint NULL REFERENCES "exchanges_broker" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX "exchanges_parserun_exchange_id_7fe60616" ON "exchanges_parserun" ("exchange_id");
CREATE INDEX "exchanges_participant_bin_e2dbc8e5" ON "exchanges_participant" ("bin");
CREATE INDEX "exchanges_p_name_2c3aac_idx" ON "exchanges_participant" ("name");
CREATE INDEX "exchanges_product_code_38dc7e30" ON "exchanges_product" ("code");
CREATE INDEX "exchanges_p_name_85fc6d_idx" ON "exchanges_product" ("name");
CREATE INDEX "exchanges_trade_trade_date_14b06db5" ON "exchanges_trade" ("trade_date");
CREATE INDEX "exchanges_trade_amount_8b7fef58" ON "exchanges_trade" ("amount");
CREATE INDEX "exchanges_trade_buyer_id_6a69ab82" ON "exchanges_trade" ("buyer_id");
CREATE INDEX "exchanges_trade_buyer_broker_id_786baff5" ON "exchanges_trade" ("buyer_broker_id");
CREATE INDEX "exchanges_trade_exchange_id_6d652b3e" ON "exchanges_trade" ("exchange_id");
CREATE INDEX "exchanges_trade_parse_run_id_c4fcda2f" ON "exchanges_trade" ("parse_run_id");
CREATE INDEX "exchanges_trade_product_id_4847128e" ON "exchanges_trade" ("product_id");
CREATE INDEX "exchanges_trade_seller_id_84aefc02" ON "exchanges_trade" ("seller_id");
CREATE INDEX "exchanges_trade_seller_broker_id_a293f847" ON "exchanges_trade" ("seller_broker_id");
CREATE INDEX "exchanges_t_exchang_4f1ab0_idx" ON "exchanges_trade" ("exchange_id", "trade_date");
CREATE INDEX "exchanges_t_deliver_77da9d_idx" ON "exchanges_trade" ("delivery_place");
CREATE INDEX "exchanges_news_published_at_19335860" ON "exchanges_news" ("published_at");
CREATE INDEX "exchanges_news_exchange_id_cf0c1a7a" ON "exchanges_news" ("exchange_id");
COMMIT;
